pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 timestamp, uint256 blockNumber) public {
        timestamp = bound(timestamp, 1, type(uint256).max - 1);
        blockNumber = bound(blockNumber, 1, type(uint256).max);
        vm.warp(timestamp);
        vm.roll(blockNumber);
        vm.deal(address(this), 10 ether);
        (bool firstOk,) = address(c).call{value: 10 ether}("");
        require(firstOk, "first call must succeed");

        // Now attempt a second call with the same timestamp.
        vm.warp(timestamp);
        vm.roll(blockNumber + 1);
        vm.deal(address(this), 10 ether);
        (bool secondOk,) = address(c).call{value: 10 ether}("");

        // If the second call succeeded, pastBlockTime must be > timestamp (since it was set to timestamp on first call).
        // If it reverted, the invariant holds vacuously.
        assertTrue(!secondOk || c.pastBlockTime() > timestamp);
    }
}

