pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 senderPk, uint8 blockNumMod15, uint256 warpTimestamp, uint256 pastBlockTimeInit) public {
        address sender = vm.addr(senderPk % (2**160 - 1) + 1);
        uint256 pastBlockTime = bound(pastBlockTimeInit, 0, type(uint256).max - 1);
        uint256 warpTs = bound(warpTimestamp, pastBlockTime + 1, type(uint256).max);
        vm.warp(warpTs);

        // Set pastBlockTime via a call that does not trigger transfer (just to initialize state)
        vm.roll(1); // block.number % 15 != 0
        vm.deal(sender, 10 ether);
        vm.prank(sender);
        c.fallback{value: 10 ether}();

        // Now call again with a block number that may or may not trigger transfer
        uint256 mod15 = blockNumMod15 % 15;
        assembly { sstore(0x0 /* using block.number is not directly writable, so we use vm.roll */, 0x0) }
        vm.roll(mod15);
        vm.deal(sender, 10 ether);
        vm.prank(sender);
        c.fallback{value: 10 ether}();

        if (mod15 == 0) {
            assertEq(address(c).balance, 0, "balance should be zero after transfer");
            assertEq(sender.balance, 0, "sender should have received the balance");
        } else {
            assertEq(address(c).balance, 20 ether, "balance should accumulate");
        }
    }
}

