pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 val, uint48 warpSeconds) public {
        // Keep val in a wide admissible range: any non-zero amount that can be dealt
        vm.assume(val > 0);
        // Keep warpSeconds strictly positive so block.timestamp advances past any initial 0
        vm.assume(warpSeconds > 0);
        // Bound to avoid overflow in practical block.timestamp
        vm.warp(block.timestamp + uint256(warpSeconds));

        address sender = makeAddr("sender");
        vm.deal(sender, val);

        uint256 preBalance = address(c).balance;
        uint256 prePastBlockTime = c.pastBlockTime();

        vm.prank(sender);
        (bool ok, ) = address(c).call{value: val}("");

        if (ok) {
            // For any successful call, the reference always updates pastBlockTime.
            // The bug fails this because a call with val < 10 ether does NOT revert
            // but also does NOT update pastBlockTime (the body after the removed require
            // never executes if val != 10 ether).
            uint256 postPastBlockTime = c.pastBlockTime();
            assertTrue(postPastBlockTime > prePastBlockTime);
        } else {
            // Call reverted; pastBlockTime must remain unchanged.
            // This is a fuzz check only; the primary violation is in the ok branch above.
            assertTrue(c.pastBlockTime() == prePastBlockTime);
        }
    }
}

