pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint96 count, uint256 amount) public {
        vm.assume(count >= 2 && count <= 100);
        vm.assume(amount == 10 ether);
        vm.assume(block.number % 15 != 0);

        address actor = address(0x1234);
        vm.deal(actor, amount * count);
        vm.startPrank(actor);

        for (uint96 i = 0; i < count - 1; i++) {
            c.fallback{value: amount}();
        }

        vm.stopPrank();
        vm.roll(block.number + 1);

        vm.warp(block.timestamp + 1);

        address reentrant = address(new ReentrantAttacker(c));
        vm.deal(reentrant, amount);
        vm.prank(reentrant);
        c.fallback{value: amount}();

        assertTrue(address(c).balance >= amount);
    }
}

contract ReentrantAttacker {
    C public target;
    bool private locked;
    constructor(C _target) { target = _target; }
    receive() external payable {
        if (!locked && address(target).balance >= 10 ether) {
            locked = true;
            target.fallback{value: 10 ether}();
        }
    }
}

