import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 blockNum, uint256 blockTime, uint256 prevBlockTime) public {
        vm.assume(blockTime > prevBlockTime);
        vm.assume(blockNum > 0);
        vm.assume(prevBlockTime < type(uint256).max);

        // Set up initial state with a past call
        vm.deal(address(this), 10 ether);
        vm.warp(prevBlockTime);
        vm.roll(1);
        c.fallback{value: 10 ether}();

        // Now make a second call with fuzzed block number and time
        vm.deal(address(this), 10 ether);
        vm.warp(blockTime);
        vm.roll(blockNum);
        bool ok;
        try c.fallback{value: 10 ether}() { ok = true; } catch { ok = false; }

        // If the second call did not revert, pastBlockTime must equal blockTime (no requirement on its relation to previous pastBlockTime)
        // But the reference contract ensures it only succeeds if blockTime > previous pastBlockTime.
        // The general rule: the second call can only succeed if blockTime > prevBlockTime.
        // The buggy version sets pastBlockTime before the check, making blockTime > pastBlockTime always true immediately after assignment,
        // so it succeeds even when blockTime <= prevBlockTime, violating the rule.
        assertTrue(!ok || blockTime > prevBlockTime);
    }
}

