        (bool ok1,) = address(c).call{value: amount}("");
        require(ok1);
        uint256 firstPastBlockTime = c.pastBlockTime();

        vm.warp(warp2);
        vm.roll(roll2);
        vm.prank(sender);
        (bool ok2,) = address(c).call{value: amount}("");
        require(ok2);
        uint256 secondPastBlockTime = c.pastBlockTime();

        assertTrue(firstPastBlockTime < secondPastBlockTime);
    }
}

