contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount, uint256 warp1, uint256 warp2, uint256 roll) public {
        // Restrict amount to exactly 10 ether (the contract requirement)
        amount = bound(amount, 10 ether, 10 ether);
        // Warp times must be sensible and distinct; keep domain wide
        warp1 = bound(warp1, 1, type(uint64).max);
        warp2 = bound(warp2, warp1 + 1, type(uint64).max);
        // Make block.number not divisible by 15 to avoid transfer reverts interfering
        roll = bound(roll, 1, type(uint64).max);
        vm.assume(roll % 15 != 0);

        // First call
        vm.warp(warp1);
        vm.roll(roll);
        vm.deal(address(this), 10 ether);
        c.f{value: 10 ether}();

        // Second call with timestamp <= pastBlockTime (which should be warp1)
        // The buggy version sets pastBlockTime before the check, so the check uses the current block.timestamp,
        // making block.timestamp > pastBlockTime always true (since pastBlockTime was just set to block.timestamp),
        // thus the second call never reverts due to the timestamp check.
        // The correct version has pastBlockTime == warp1, so a call at warp1 should revert.
        vm.warp(warp1);
        vm.roll(roll + 1); // ensure not divisible by 15
        vm.deal(address(this), 10 ether);
        bool ok;
        try c.f{value: 10 ether}() { ok = true; } catch { ok = false; }

        // In the reference C, the second call must revert because block.timestamp (warp1) == pastBlockTime (warp1),
        // violating the strict > check.
        // In the buggy version, pastBlockTime is overwritten before the check, so it passes.
        assertTrue(!ok);
    }
}

