pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount, uint8 fuzzBlockDelta, bool sameBlock) public {
        amount = bound(amount, 1, 10000 ether);
        fuzzBlockDelta = uint8(bound(fuzzBlockDelta, 1, 255));

        // Ensure c has no ether for the first call
        vm.deal(address(c), 0);
        // Fund the caller
        vm.deal(address(this), amount * 2 + 10 ether);

        uint256 firstBlock = uint256(block.number);
        // Move to a block where block.number % 15 != 0 so no transfer happens
        vm.roll(firstBlock + 1);
        vm.warp(1000);
        c.f{value: 10 ether}();

        // Move forward in time but possibly stay in the same block
        vm.warp(1000 + uint256(fuzzBlockDelta));
        if (sameBlock) {
            vm.roll(block.number); // keep the same block
            // Ensure block.number % 15 != 0 so no transfer and no selfdestruct
            if (block.number % 15 == 0) {
                vm.roll(block.number + 1);
                // still same error? block changed but we want minimal difference. Just skip if this happens.
            }
        } else {
            vm.roll(block.number + 1);
        }

        // Second call: should revert if sameBlock is true because block.timestamp == pastBlockTime (from first call)
        bool ok;
        try c.f{value: 10 ether}() {
            ok = true;
        } catch {
            ok = false;
        }

        if (sameBlock) {
            // In the original, the call MUST revert because block.timestamp is NOT > pastBlockTime (they are equal)
            assertTrue(!ok);
        } else {
            // In the original, the call MUST succeed because block.timestamp > pastBlockTime
            assertTrue(ok);
        }
    }
}
